const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";
pres.author = "Our World in Data / Global Carbon Budget 2025";

// ─── COLOR PALETTE ───────────────────────────────────────────────────────────
const C = {
  darkBg:   "0F2236",   // deep navy – title/conclusion slides
  lightBg:  "F4F7F9",   // off-white – content slides
  teal:     "0D7FA5",   // primary teal accent
  tealDark: "0A5F7A",   // darker teal for chart fills
  tealMid:  "1499C4",   // mid teal
  tealPale: "D6F0F7",   // very pale teal for area fills
  red:      "C0392B",   // warm red for emphasis
  orange:   "E67E22",   // orange for contrasting data
  blue:     "2471A3",   // blue for "decline" data
  green:    "1E8449",   // green
  gray:     "5D6D7E",   // muted text
  lightGray:"EAF0F6",   // very light bg for cards
  white:    "FFFFFF",
  nearBlack: "1C2833",
};

// ─── HELPERS ──────────────────────────────────────────────────────────────────
function makeShadow() {
  return { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.10 };
}

// ─── SLIDE 1: TITLE ──────────────────────────────────────────────────────────
{
  let slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Teal accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.tealMid }, line: { color: C.tealMid, width: 0 }
  });

  // Large vertical accent strip on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });

  // Title
  slide.addText("Global CO₂ Emissions", {
    x: 0.55, y: 1.15, w: 9, h: 0.95,
    fontSize: 44, bold: true, color: C.white, fontFace: "Trebuchet MS", align: "left"
  });
  slide.addText("Who Emits, How Much, and What's Changing", {
    x: 0.55, y: 2.05, w: 9, h: 0.6,
    fontSize: 24, color: C.tealMid, fontFace: "Trebuchet MS", align: "left"
  });

  // Horizontal divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.55, y: 2.85, w: 3.5, h: 0.04,
    fill: { color: C.tealMid }, line: { color: C.tealMid, width: 0 }
  });

  // Scope line
  slide.addText("Scope: Fossil fuels & industry  ·  1750–2024", {
    x: 0.55, y: 3.05, w: 9, h: 0.38,
    fontSize: 13, color: "A9B8C4", fontFace: "Calibri", italic: true, align: "left"
  });

  // Data source
  slide.addText([
    { text: "Data: ", options: { bold: true } },
    { text: "Global Carbon Budget 2025 via Our World in Data", options: {} },
    { text: "  ·  Authors: Hannah Ritchie & Max Roser", options: {} }
  ], {
    x: 0.55, y: 3.55, w: 9, h: 0.38,
    fontSize: 12, color: "7A8FA3", fontFace: "Calibri", align: "left"
  });

  // Audience tag
  slide.addText("Audience: Policy analysts  ·  Climate negotiators  ·  Sustainability researchers", {
    x: 0.55, y: 4.05, w: 9, h: 0.32,
    fontSize: 11, color: "5C7080", fontFace: "Calibri", align: "left"
  });

  // Decorative bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.35, w: 10, h: 0.275,
    fill: { color: C.teal, transparency: 60 }, line: { color: C.teal, width: 0 }
  });
}

// ─── SLIDE 2: GLOBAL EMISSIONS GROWTH (Line/Area chart) ───────────────────────
{
  let slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Header bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: C.darkBg }, line: { color: C.darkBg, width: 0 }
  });
  slide.addText("Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today", {
    x: 0.35, y: 0.08, w: 9.3, h: 0.56,
    fontSize: 17, bold: true, color: C.white, fontFace: "Trebuchet MS", align: "left", valign: "middle"
  });

  // Line/Area chart data (approximate trajectory from source_brief)
  const labels = [
    "1750","1800","1850","1900","1950","1960","1970","1980","1990","2000","2010","2020","2024"
  ];
  const values = [0.1, 0.3, 1.0, 5.0, 6.2, 9.4, 15.2, 19.6, 22.5, 25.1, 33.3, 34.8, 37.0];

  slide.addChart(pres.charts.AREA, [{
    name: "CO₂ Emissions (Bt)",
    labels: labels,
    values: values
  }], {
    x: 0.35, y: 0.88, w: 9.3, h: 3.85,
    chartColors: [C.tealMid],
    chartArea: { fill: { color: C.white }, roundedCorners: false },
    catAxisLabelColor: C.gray,
    catAxisLabelFontSize: 9,
    valAxisLabelColor: C.gray,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "D5E0EA", size: 0.5 },
    catGridLine: { style: "none" },
    lineSize: 2,
    lineSmooth: true,
    showValue: false,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 40,
    catAxisInterval: 1,
  });

  // Annotation callouts
  // 1950 inflection
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.45, y: 3.18, w: 0.04, h: 0.45,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  slide.addText("~6 Bt", {
    x: 3.05, y: 2.82, w: 0.85, h: 0.36,
    fontSize: 11, bold: true, color: C.teal, fontFace: "Calibri", align: "center"
  });

  // 2024
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 9.25, y: 0.98, w: 0.04, h: 0.45,
    fill: { color: C.red }, line: { color: C.red, width: 0 }
  });
  slide.addText("~37 Bt", {
    x: 8.85, y: 0.62, w: 0.85, h: 0.36,
    fontSize: 11, bold: true, color: C.red, fontFace: "Calibri", align: "center"
  });

  // Key message box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 4.88, w: 9.3, h: 0.56,
    fill: { color: C.darkBg }, line: { color: C.darkBg, width: 0 }
  });
  slide.addText(
    "Post-WWII acceleration drove a 6× increase in 70 years. Growth has slowed — but emissions have not yet peaked.",
    {
      x: 0.55, y: 4.88, w: 9.0, h: 0.56,
      fontSize: 12, color: C.white, fontFace: "Calibri", italic: true, valign: "middle", align: "center"
    }
  );
}

// ─── SLIDE 3: REGIONAL SHARE SHIFT (Stacked area) ────────────────────────────
{
  let slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: C.darkBg }, line: { color: C.darkBg, width: 0 }
  });
  slide.addText("Europe and the US Fell from >90% of Emissions in 1900 to Under One-Third Today", {
    x: 0.35, y: 0.08, w: 9.3, h: 0.56,
    fontSize: 16, bold: true, color: C.white, fontFace: "Trebuchet MS", align: "left", valign: "middle"
  });

  // Stacked area chart — approximate regional shares over time
  const yrs = ["1900","1920","1940","1960","1980","2000","2024"];
