  slide.addText("Even among wealthy nations, per capita emissions vary widely. France & the UK (~4–6 t) emit far less than the US (14 t) due to nuclear & renewable energy shares.", {
    x: 6.85, y: 3.88, w: 2.75, h: 1.0,
    fontSize: 9.5, color: C.nearBlack, fontFace: "Calibri"
  });

  // Bottom note
