  });

  // Insight cards on right
  const insights = [
    { highlight: "US: 14 t", body: "3× the world average. Highest among large economies.", color: C.red },
    { highlight: "China: 9 t", body: "Largest total emitter, but per capita still 1/3 below the US.", color: C.orange },
    { highlight: "India: 2 t", body: "Very low per capita despite being 3rd largest total emitter.", color: C.teal },
    { highlight: "Kenya: 0.4 t", body: "Comparable to other Sub-Saharan African nations.", color: "27AE60" },
  ];

  let iY = 0.85;
  insights.forEach(ins => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.75, y: iY, w: 2.95, h: 0.9,
