  });
}

// ─── SLIDE 7: 2024 ANNUAL CHANGE (Diverging bar chart) ───────────────────────
{
  let slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
