  ], {
    x: 6.95, y: 2.0, w: 2.75, h: 1.0,
    fontSize: 9, color: C.nearBlack, fontFace: "Calibri"
  });

  // Net note
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.95, y: 3.2, w: 2.75, h: 0.95,
    fill: { color: C.lightGray }, line: { color: C.teal, width: 1 }
  });
  slide.addText("Net result: global emissions in 2024 remained roughly flat vs. 2023 — no significant increase, but no peak yet.", {
    x: 7.05, y: 3.28, w: 2.55, h: 0.8,
    fontSize: 9.5, color: C.nearBlack, fontFace: "Calibri", italic: true
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data  ·  2024 annual change", {
    x: 0.3, y: 5.25, w: 6.5, h: 0.28,
    fontSize: 9, color: C.gray, fontFace: "Calibri"
  });
}

