    // Body
    slide.addText(tk.body, {
      x: cx + 0.1, y: 2.95, w: cardW - 0.2, h: 1.55,
      fontSize: 9.5, color: "C8D8E4", fontFace: "Calibri", align: "center", valign: "top"
