    dataLabelColor: C.nearBlack,
    dataLabelFontSize: 10,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 16,
  });

  // Energy mix explanation card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: 0.85, w: 4.7, h: 3.6,
    fill: { color: C.white }, line: { color: C.teal, width: 1 },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });

  slide.addText("Why the gap?", {
    x: 5.15, y: 0.95, w: 4.4, h: 0.38,
    fontSize: 14, bold: true, color: C.teal, fontFace: "Trebuchet MS"
  });

  slide.addText("Countries with similar prosperity levels can have very different per capita emissions depending on their energy mix.", {
    x: 5.15, y: 1.4, w: 4.4, h: 0.65,
    fontSize: 11, color: C.nearBlack, fontFace: "Calibri"
  });

  // Energy mix examples
  const mixExamples = [
    { country: "France", drivers: "~70% nuclear + renewables → ~4 t/capita", icon: "⚛", color: C.teal },
    { country: "UK",     drivers: "~45% renewables + gas shift → ~4 t/capita", icon: "☀", color: "2471A3" },
    { country: "Germany",drivers: "~50% fossil-based electricity → ~8.5 t/capita", icon: "☭", color: C.orange },
    { country: "US",     drivers: "~60% fossil-based electricity → ~14 t/capita", icon: "⚡", color: C.red },
  ];

  let exY = 2.15;
  mixExamples.forEach(ex => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.15, y: exY, w: 4.4, h: 0.5,
      fill: { color: C.lightGray }, line: { color: ex.color, width: 0 }
