      fill: { color: ex.color }, line: { color: ex.color, width: 0 }
    });
    slide.addText(ex.country, {
      x: 5.3, y: exY + 0.04, w: 1.1, h: 0.22,
      fontSize: 10, bold: true, color: ex.color, fontFace: "Trebuchet MS"
    });
    slide.addText(ex.drivers, {
