    },
    {
      num: "3",
      title: "Historical responsibility: Europe & US",
      body: "Europe and the US produced >90% of cumulative emissions. Today they account for <27% of annual output."
    },
    {
      num: "4",
      title: "150× per capita gap persists",
      body: "A person in Chad (~0.1 t/yr) emits 150× less than a person in the US (~14 t/yr)."
    },
    {
      num: "5",
      title: "Energy policy can decouple prosperity & emissions",
      body: "France and the UK show that wealthy nations can achieve low per capita emissions through nuclear & renewable energy."
    },
  ];

