// Five takeaway cards
const takeaways = [
  {
    num: "1",
    title: "No peak yet",
    body: "Global CO₂ from fossil fuels exceed 35 Bt/yr — and have not yet peaked despite slowing growth."
  },
  {
    num: "2",
    title: "China is #1, but per capita still below US",
    body: "China alone emits ~31% of global total, yet per capita (~9 t) remains well below the US (~14 t)."
  },
  {
    num: "3",
    title: "Historical responsibility: Europe & US",
    body: "Europe and the US produced >90% of cumulative emissions. Today they account for <27% of annual output."
  },
  {
    num: "4",
    title: "150× per capita gap persists",
    body: "A person in Chad (~0.1 t/yr) emits 150× less than a person in the US (~14 t/yr)."
  },
  {
    num: "5",
    title: "Energy policy can decouple prosperity & emissions",
    body: "France and the UK show that wealthy nations can achieve low per capita emissions through nuclear & renewable energy."
  },
];

let cardX = 0.55;
const cardW = 1.78;
const cardGap = 0.12;

takeaways.forEach((tk) => {
  const cx = cardX + (takeaways.indexOf(tk)) * (cardW + cardGap);

  // Card background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: 1.5, w: cardW, h: 3.1,
    fill: { color: C.white, transparency: 8 }, line: { color: C.tealMid, width: 0.5 },
  });

  // Number circle
  slide.addShape(pres.shapes.OVAL, {
    x: cx + 0.64, y: 1.65, w: 0.5, h: 0.5,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  slide.addText(tk.num, {
    x: cx + 0.64, y: 1.65, w: 0.5, h: 0.5,
    fontSize: 16, bold: true, color: C.white, fontFace: "Trebuchet MS",
    align: "center", valign: "middle"
  });

  // Title
  slide.addText(tk.title, {
    x: cx + 0.1, y: 2.28, w: cardW - 0.2, h: 0.65,
    fontSize: 11, bold: true, color: C.tealMid, fontFace: "Trebuchet MS", align: "center"
  });

  // Body
  slide.addText(tk.body, {
    x: cx + 0.1, y: 2.95, w: cardW - 0.2, h: 1.55,
    fontSize: 9.5, color: "C8D8E4", fontFace: "Calibri", align: "center", valign: "top"
  });

  cardX = cx;
});

// Source footer
slide.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 4.85, w: 10, h: 0.775,
  fill: { color: C.teal, transparency: 75 }, line: { color: C.teal, width: 0 }
});
slide.addText("Data: Global Carbon Budget 2025 via Our World in Data  ·  Hannah Ritchie & Max Roser", {
  x: 0.55, y: 4.92, w: 9.0, h: 0.3,
  fontSize: 10, color: "9AB4C4", fontFace: "Calibri"
});
slide.addText("Fossil fuels & industry  ·  1750–2024  ·  OurWorldInData.org/co2-emissions", {
  x: 0.55, y: 5.22, w: 9.0, h: 0.28,
  fontSize: 9, color: "7A9AAA", fontFace: "Calibri"
});

