});
slide.addText("Data: Global Carbon Budget 2025 via Our World in Data  ·  Hannah Ritchie & Max Roser", {
  x: 0.55, y: 4.92, w: 9.0, h: 0.3,
  fontSize: 10, color: "9AB4C4", fontFace: "Calibri"
});
slide.addText("Fossil fuels & industry  ·  1750–2024  ·  OurWorldInData.org/co2-emissions", {
