// Slide 6 spacing audit
const chart = { x: 0.5, y: 0.88, w: 6.0, h: 3.6 };
const refLine = 2.98;
const cards = [{y:0.88},{y:1.95},{y:3.02},{y:4.09}];
const cardH = 0.95;
const footer = { y: 5.1, h: 0.28 };
const SLIDE_H = 5.625;

console.log('=== SLIDE 6 AUDIT ===');
console.log('Chart: y=' + chart.y + ' → bottom=' + (chart.y+chart.h));
console.log('Ref line at y=' + refLine + ' (within chart: ' + (refLine > chart.y && refLine < chart.y+chart.h) + ')');
cards.forEach((c,i) => {
  const bottom = c.y + cardH;
  const fits = bottom <= footer.y;
  console.log('Card '+(i+1)+': y='+c.y+' → bottom='+bottom+' ('+ (fits?'OK':'OVERFLOW')+')');
});
console.log('Footer: y='+footer.y+' → bottom='+(footer.y+footer.h)+' (max='+SLIDE_H+')');
console.log('All cards fit: ' + cards.every((c,i) => c.y+cardH <= footer.y));
console.log();
console.log('=== SLIDE 9 AUDIT ===');
const cards9 = [];
for(let i=0;i<5;i++) cards9.push({ x: 0.5 + i*(1.9+0.1), w: 1.9 });
cards9.forEach((c,i) => console.log('Card '+(i+1)+': x='+c.x+' → right='+(c.x+c.w)+' (max=10)'));
console.log('Last card right: '+(cards9[4].x+cards9[4].w)+' (max=10)');
"

